'use strict';
const cases = [
 {title:'Il mistero delle ciambelle',place:'PIAZZA DEL SOLE',icon:'🍩',villain:'Gino il Golosone',brief:'Sono sparite le ciambelle! Parla con la fornaia Ada: forse ha visto qualcosa.',npc:'Ada',npcIcon:'👩‍🍳',item:'Ciambella',itemIcon:'🍩',target:'Gino',targetIcon:'🦝',clue:'Briciole',clueIcon:'🔍',dialog:'Ada: «Una scia di briciole porta a Gino! Prendi la ciambella sul banco: gli piace tanto.»',found:'Queste briciole sono freschissime. Qualcuno ha fatto una colazione enorme!',resolved:'Gino: «Volevo fare una festa, ma ho dimenticato di chiedere! Restituisco tutto e aiuto Ada a cucinare.»',hint:'Parla con Ada, osserva le briciole e raccogli la ciambella. Poi selezionala nello zainetto e tocca Gino.'},
 {title:'Il ladro di campanelli',place:'VIA DELLE BICICLETTE',icon:'🔔',villain:'Nino Scampanino',brief:'Le biciclette non fanno più drin drin! Il meccanico Teo ha bisogno di te.',npc:'Teo',npcIcon:'👨‍🔧',item:'Campanello',itemIcon:'🔔',target:'Nino',targetIcon:'🦊',clue:'Impronte',clueIcon:'🐾',dialog:'Teo: «Nino colleziona suoni! Le sue impronte sono vicino alla fontana. Questo campanello è un regalo per lui.»',found:'Impronte a zig zag! Nino saltella quando sente un campanello.',resolved:'Nino: «Drin! Questo è mio? Allora riporto gli altri. Aprirò un museo dei suoni… con il permesso!»',hint:'Parla con Teo. Guarda le impronte. Raccogli il campanello e usalo su Nino.'},
 {title:'Operazione gelato gigante',place:'LUNGOMARE DEI GELATI',icon:'🍦',villain:'La Banda del Cono',brief:'La Banda del Cono ha nascosto il carretto dei gelati. Chiedi a Bea dove cercare.',npc:'Bea',npcIcon:'👩‍🌾',item:'Cucchiaio',itemIcon:'🥄',target:'Banda del Cono',targetIcon:'🐻',clue:'Gocce rosa',clueIcon:'🍓',dialog:'Bea: «Segui le gocce alla fragola! Il loro cono gigante si è incastrato. Porta questo cucchiaio.»',found:'Una pista rosa! Il gelato sta sciogliendosi vicino al nascondiglio.',resolved:'La Banda: «Ci aiuti a liberare il cono? Riportiamo il carretto! D’ora in poi faremo la fila come tutti.»',hint:'Parla con Bea, guarda le gocce rosa e prendi il cucchiaio. Selezionalo e tocca la Banda.'},
 {title:'Il colpo della corona di carta',place:'PIAZZA DEL TEATRO',icon:'👑',villain:'Conte Pasticcio',brief:'Il Conte Pasticcio ha preso la corona del teatro. Il direttore Leo ti aspetta.',npc:'Leo',npcIcon:'🧑‍🎨',item:'Invito',itemIcon:'✉️',target:'Conte Pasticcio',targetIcon:'🦁',clue:'Coriandoli',clueIcon:'🎊',dialog:'Leo: «Il Conte vuole recitare! Segui i coriandoli e portagli un invito ufficiale allo spettacolo.»',found:'Coriandoli dorati! Il Conte prova il suo ingresso trionfale dietro il teatro.',resolved:'Il Conte: «Un ruolo per me? Allora restituisco la corona. Posso fare il re dei pasticci?»',hint:'Parla con Leo, cerca i coriandoli e raccogli l’invito. Usalo sul Conte Pasticcio.'},
 {title:'La fabbrica degli scherzi',place:'PORTO DEI PACCHI',icon:'📦',villain:'Professor Scombussolo',brief:'Il Professore ha scambiato tutti i pacchi della città! La postina Mia ha un indizio.',npc:'Mia',npcIcon:'👩‍🚀',item:'Etichette',itemIcon:'🏷️',target:'Professore',targetIcon:'🦉',clue:'Pacco buffo',clueIcon:'📦',dialog:'Mia: «Una macchina incolla le etichette al contrario! Controlla il pacco e porta queste etichette colorate.»',found:'Una scarpa nella scatola dei biscotti! Le etichette sono tutte capovolte.',resolved:'Il Professore: «Ops! Con queste etichette sistemo la macchina. Riordinerò ogni pacco: promessa di inventore!»',hint:'Parla con Mia, guarda il pacco buffo e prendi le etichette. Usale sul Professore.'},
 {title:'Il grande mistero delle nuvole',place:'COLLINA DEL FARO',icon:'☁️',villain:'Capitan Nebbione',brief:'Capitan Nebbione ha nascosto il faro con una nuvola gigante. Olmo sa come aiutarti!',npc:'Olmo',npcIcon:'🧙‍♂️',item:'Ventaglio',itemIcon:'🪭',target:'Neb bione'.replace(' ',''),targetIcon:'🏴‍☠️',clue:'Macchina delle nuvole',clueIcon:'⚙️',dialog:'Olmo: «Neb bione voleva un po’ d’ombra! Guarda la macchina: un ventaglio può spostare la nuvola.»',found:'La macchina produce nuvole a forma di patata. Il faro ha bisogno di un po’ di vento!',resolved:'Capitan Nebbione: «Ora le barche vedono il faro! Userò le mie nuvole per ombreggiare i picnic. Sei il miglior detective di Porto Buffo!»',hint:'Parla con Olmo, osserva la macchina e raccogli il ventaglio. Usalo su Capitan Nebbione.'}
];
const vehicles=[['🚲','Bicicletta','Per i primi misteri del quartiere.'],['🛵','Moto','Sfreccia verso nuovi indizi.'],['🚓','Auto','La prima vera pattuglia di Pippo.'],['🏎️','Auto sportiva','Per i casi fuori città.'],['🚚','Camion','Trasporta anche gli indizi giganti.'],['🚁','Elicottero','Il cielo non ha più segreti!']];
const stations=[['🏠','Piccolo ufficio'],['📻','Sala radio'],['🔬','Laboratorio degli indizi'],['🗺️','Sala delle mappe'],['🛠️','Officina speciale'],['📡','Centro operativo']];
const ranks=['Agente apprendista','Agente di quartiere','Agente scelto','Ispettore','Commissario','Capo detective','Eroe di Porto Buffo'];
const initialState=()=>({version:1,caseIndex:0,completed:[],stars:0,vehicle:0,station:0,steps:[],inventory:[],voice:true});
function validateState(s){return s&&s.version===1&&Number.isInteger(s.caseIndex)&&s.caseIndex>=0&&s.caseIndex<6&&Number.isInteger(s.stars)&&s.stars>=0&&['vehicle','station'].every(k=>Number.isInteger(s[k])&&s[k]>=0&&s[k]<6)&&Array.isArray(s.completed)&&s.completed.every((v,i)=>v===i)&&s.completed.length<=6&&Array.isArray(s.steps)&&s.steps.every(v=>['talk','clue','done'].includes(v))&&Array.isArray(s.inventory)&&s.inventory.every(v=>v===cases[s.caseIndex].item)&&typeof s.voice==='boolean';}
function completeCase(s){if(!s.steps.includes('done')||s.completed.includes(s.caseIndex))return false;s.completed.push(s.caseIndex);s.stars+=5;return true;}
function purchase(s,kind,index){if(!['vehicle','station'].includes(kind)||index!==s[kind]+1||index>=6||s.completed.length<index||s.stars<2)return false;s.stars-=2;s[kind]=index;return true;}
function advance(s){const next=s.caseIndex+1;if(!s.completed.includes(s.caseIndex)||next>=6||s.vehicle<next||s.station<next)return false;s.caseIndex=next;s.steps=[];s.inventory=[];return true;}
if(typeof module!=='undefined')module.exports={cases,initialState,validateState,completeCase,purchase,advance};
if(typeof document!=='undefined'){
 const $=id=>document.getElementById(id);let state=initialState(),selected=null,saveAvailable=true;
 try{const saved=localStorage.getItem('porto_buffo_v1');if(saved){const parsed=JSON.parse(saved);if(validateState(parsed))state=parsed;else console.warn('Salvataggio non valido: nuova partita.');}}catch(error){console.warn('Lettura salvataggio non disponibile:',error);saveAvailable=false;}
 function save(){try{localStorage.setItem('porto_buffo_v1',JSON.stringify(state));}catch(error){console.warn('Salvataggio non disponibile:',error);saveAvailable=false;}render();}
 function speak(text){if(state.voice&&'speechSynthesis'in window){speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='it-IT';utterance.rate=.85;speechSynthesis.speak(utterance);}}
 function say(text,name='CAPITANA LINA',icon='👩‍✈️'){ $('message').textContent=text;$('speaker').textContent=name;$('speakerIcon').textContent=icon;speak(text);}
 function view(name){['play','garage','station','cases'].forEach(id=>$(id).hidden=id!==name);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===name));render();}
 function render(){const c=cases[state.caseIndex],done=state.completed.includes(state.caseIndex);$('rank').textContent=ranks[state.completed.length];$('stars').textContent=`★ ${state.stars} stelle`;$('voice').textContent=state.voice?'🔊 Voce: sì':'🔇 Voce: no';$('caseNumber').textContent=`CASO ${state.caseIndex+1} DI 6`;$('caseTitle').textContent=c.title;$('location').textContent=c.place;$('progress').textContent=done?'✓ Caso risolto':`${state.steps.filter(x=>x!=='done').length} / 2 indizi`;
 const objects=[['talk',c.npcIcon,c.npc,18,83],['clue',c.clueIcon,c.clue,36,12],['item',c.itemIcon,c.item,68,40],['target',c.targetIcon,c.target,85,90]];
 $('hotspots').replaceChildren();objects.forEach(([action,icon,label,x,bottom])=>{if(action==='item'&&(state.inventory.includes(c.item)||done))return;const button=document.createElement('button');button.className='hotspot'+(state.steps.includes(action)?' solved':'');button.style.left=x+'%';button.style.bottom=bottom+'px';button.setAttribute('aria-label',label);const object=document.createElement('span');object.className='object';object.textContent=icon;const caption=document.createElement('span');caption.className='label';caption.textContent=label;button.append(object,caption);button.onclick=()=>interact(action,x);$('hotspots').append(button);});
 $('inventory').replaceChildren();if(!state.inventory.length){const empty=document.createElement('span');empty.textContent='Ancora vuoto. Esploriamo!';empty.style.fontSize='13px';$('inventory').append(empty);}state.inventory.forEach(item=>{const b=document.createElement('button');b.textContent=`${c.itemIcon} ${item}`;b.classList.toggle('selected',selected===item);b.onclick=()=>{selected=selected===item?null:item;render();say(selected?`Ora tocca ${c.target} per usare ${item.toLowerCase()}.`:'Oggetto rimesso nello zainetto.');};$('inventory').append(b);});
 $('next').hidden=!done||state.caseIndex===5;$('next').textContent=state.vehicle>state.caseIndex&&state.station>state.caseIndex?'Prossimo caso →':'Prepara il prossimo caso →';$('instruction').textContent=saveAvailable?'Tocca, raccogli, poi usa gli oggetti!':'Salvataggio non disponibile: tieni aperta questa pagina.';
 renderShop('vehicles',vehicles,'vehicle');renderShop('upgrades',stations,'station');$('stationIcons').textContent=stations.slice(1,state.station+1).map(x=>x[0]).join(' ');$('caseCards').replaceChildren();cases.forEach((entry,i)=>{const card=document.createElement('article');card.className='card';const icon=document.createElement('div');icon.className='icon';icon.textContent=entry.icon;const title=document.createElement('h3');title.textContent=entry.title;const p=document.createElement('p');p.textContent=state.completed.includes(i)?'✓ Risolto!':i===state.caseIndex?'🔎 Caso in corso':`🔒 Richiede ${vehicles[i][1].toLowerCase()} e ${stations[i][1].toLowerCase()}`;card.append(icon,title,p);$('caseCards').append(card);});}
 function renderShop(id,items,kind){$(id).replaceChildren();items.forEach(([icon,title,description],i)=>{const card=document.createElement('article');card.className='card'+(state[kind]===i?' owned':'');const art=document.createElement('div');art.className='icon';art.textContent=icon;const h=document.createElement('h3');h.textContent=title;const p=document.createElement('p');p.textContent=description||`Il reparto per il caso ${i+1}.`;const b=document.createElement('button');b.textContent=i<=state[kind]?(i===state[kind]?'✓ In uso':'✓ Sbloccato'):state.completed.length<i?`🔒 Risolvi ${i} casi`:'★ 2 stelle · Sblocca';b.disabled=i!==state[kind]+1||state.completed.length<i||state.stars<2;b.onclick=()=>{if(purchase(state,kind,i)){save();say(`${title} sbloccato! Torna alla missione per continuare.`);}};card.append(art,h,p,b);$(id).append(card);});}
 function interact(action,x){const c=cases[state.caseIndex];$('officer').style.left=Math.max(3,x-7)+'%';if(state.completed.includes(state.caseIndex)){say('Caso risolto! Guarda il garage e la stazione, oppure continua con il prossimo caso.');return;}if(action==='talk'){if(!state.steps.includes('talk'))state.steps.push('talk');say(c.dialog,c.npc.toUpperCase(),c.npcIcon);}if(action==='clue'){if(!state.steps.includes('clue'))state.steps.push('clue');say(c.found,'PIPPO','👮');}if(action==='item'){if(!state.inventory.includes(c.item))state.inventory.push(c.item);say(`${c.item} raccolto! Toccalo nello zainetto per usarlo.`,'PIPPO','👮');}if(action==='target'){if(selected!==c.item){say(`Prima scegli un oggetto nello zainetto e poi tocca ${c.target}.`,'PIPPO','👮');}else if(!state.steps.includes('talk')||!state.steps.includes('clue')){say('Prima scopriamo cosa è successo: parla con il testimone e osserva l’indizio.','PIPPO','👮');}else{state.steps.push('done');state.inventory=[];selected=null;completeCase(state);say(`${c.resolved} Caso risolto! Hai guadagnato 5 stelle.${state.completed.length===6?' Complimenti! Sei l’eroe di Porto Buffo!':' Visita garage e stazione per preparare la prossima avventura.'}`,c.villain.toUpperCase(),c.targetIcon);}}save();}
 document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>view(b.dataset.view));$('voice').onclick=()=>{state.voice=!state.voice;if(!state.voice&&'speechSynthesis'in window)speechSynthesis.cancel();save();};$('read').onclick=()=>speak($('message').textContent);$('help').onclick=()=>{view('play');say(cases[state.caseIndex].hint);};$('next').onclick=()=>{if(advance(state)){selected=null;save();say(cases[state.caseIndex].brief);}else{view(state.vehicle<=state.caseIndex?'garage':'station');say('Compra il prossimo mezzo e il prossimo reparto: costano 2 stelle ciascuno.');}};$('reset').onclick=()=>$('resetDialog').showModal();$('cancelReset').onclick=()=>$('resetDialog').close();$('confirmReset').onclick=()=>{state=initialState();selected=null;$('resetDialog').close();save();view('play');say(cases[0].brief);};render();$('message').textContent=state.completed.includes(state.caseIndex)?'Caso risolto! Prepara il prossimo caso nel garage e nella stazione.':cases[state.caseIndex].brief;
}
